+const filterButtons = Array.from(document.querySelectorAll(".filter-chip"));
+const productCards = Array.from(document.querySelectorAll(".product-card"));
+const timerElement = document.getElementById("deal-timer");
+const newsletterForm = document.querySelector(".newsletter-form");
+
+function setActiveFilter(nextFilter) {
+  filterButtons.forEach((button) => {
+    const isActive = button.dataset.filter === nextFilter;
+    button.classList.toggle("is-active", isActive);
+    button.setAttribute("aria-pressed", String(isActive));
+  });
+
+  productCards.forEach((card) => {
+    const matches = nextFilter === "all" || card.dataset.category === nextFilter;
+    card.hidden = !matches;
+  });
+}
+
+function startDealCountdown(durationInSeconds) {
+  let remaining = durationInSeconds;
+
+  const tick = () => {
+    const hours = String(Math.floor(remaining / 3600)).padStart(2, "0");
+    const minutes = String(Math.floor((remaining % 3600) / 60)).padStart(2, "0");
+    const seconds = String(remaining % 60).padStart(2, "0");
+
+    timerElement.textContent = `${hours}:${minutes}:${seconds}`;
+    remaining = remaining > 0 ? remaining - 1 : durationInSeconds;
+  };
+
+  tick();
+  window.setInterval(tick, 1000);
+}
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    setActiveFilter(button.dataset.filter);
+  });
+});
+
+newsletterForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const emailField = newsletterForm.querySelector("#email");
+
+  if (!emailField.checkValidity()) {
+    emailField.focus();
+    emailField.reportValidity();
+    return;
+  }
+
+  const submitButton = newsletterForm.querySelector('button[type="submit"]');
+  submitButton.textContent = "You're in";
+  submitButton.disabled = true;
+  submitButton.setAttribute("aria-disabled", "true");
+});
+
+setActiveFilter("all");
+startDealCountdown(8 * 60 * 60);
+

')

